package vault

import (
	"bufio"
	"fmt"
	"go/ast"
	"os"
	"path"
	"strconv"
	"strings"

	"github.com/Galdoba/go-graph/pkg/graph"
	"github.com/Galdoba/go-graph/pkg/link"
)

// MarkerField is the frontmatter field that states the file was generated by the graph. Only a
// value that reads as true claims graph ownership, so a file without the field is never removed.
const MarkerField = "generated"

// fieldOrder is the order the frontmatter fields are written in, which is what makes a rendering
// reproducible. The marker is first because ownership is decided before anything else in the file
// is read.
var fieldOrder = []string{
	MarkerField, "module", "version", "package_path", "package",
	"kind", "semantic_type", "properties",
	"file", "line", "column", "start_line", "end_line",
}

// Record is the content a note file carries: the identifier parts a location cannot carry on its
// own, the code region, and the marker. The node name and the receiver are not repeated, because
// the file name carries them.
type Record struct {
	Generated    bool
	Module       string
	Version      string
	PackagePath  string
	Package      string
	Kind         string
	SemanticType string
	Properties   []string
	File         string
	Line         int
	Column       int
	StartLine    int
	EndLine      int
}

// Content renders a note file for a record. Every line is derived from the record and the node
// collection, so the same inputs render the same bytes.
func Content(n *graph.Node, nodes []*graph.Node) string {
	return frontmatter(n) + body(n, nodes)
}

// Render writes the note file a record maps to and reports the path it wrote.
func Render(root string, n *graph.Node, nodes []*graph.Node) (string, error) {
	if err := os.MkdirAll(Folder(root, n.Package), 0o755); err != nil {
		return "", err
	}
	file := NotePath(root, n)
	if err := os.WriteFile(file, []byte(Content(n, nodes)), 0o644); err != nil {
		return "", err
	}
	return file, nil
}

// frontmatter writes the fields the record carries in the fixed order. A field the record does
// not carry is not written as an empty value.
func frontmatter(n *graph.Node) string {
	values := map[string]string{
		MarkerField:     "true",
		"module":        n.Package.ModulePath,
		"version":       n.Package.ModuleVersion,
		"package_path":  n.Package.PackagePath,
		"package":       n.Package.Name,
		"kind":          n.Kind.String(),
		"semantic_type": n.SemanticType.String(),
		"properties":    propertyLine(n.Properties),
		"file":          n.Pos.File,
		"line":          strconv.Itoa(n.Pos.Line),
		"column":        strconv.Itoa(n.Pos.Column),
		"start_line":    strconv.Itoa(n.Range.StartLine),
		"end_line":      strconv.Itoa(n.Range.EndLine),
	}

	var b strings.Builder
	b.WriteString("---\n")
	for _, field := range fieldOrder {
		if value := values[field]; value != "" {
			fmt.Fprintf(&b, "%s: %s\n", field, value)
		}
	}
	b.WriteString("---\n")
	return b.String()
}

// body states what the node is in a form that can be read without the build that produced the
// file, because the file name states the semantic type only.
func body(n *graph.Node, nodes []*graph.Node) string {
	var lines []string

	lines = append(lines, "# "+n.Name, "")

	// ## Code section
	lines = append(lines, "## Code", "", "```go")
	if doc := docComment(n); doc != "" {
		for _, line := range strings.Split(strings.TrimSpace(doc), "\n") {
			lines = append(lines, "// "+strings.TrimSpace(line))
		}
	}
	for _, line := range strings.Split(codeSnippet(n), "\n") {
		lines = append(lines, line)
	}
	lines = append(lines, "```", "## Related", "")

	links := incomingLinks(n, nodes)
	if len(links) == 0 {
		lines = append(lines, "None detected")
	} else {
		for _, l := range links {
			lines = append(lines, "- "+l)
		}
	}

	return strings.Join(lines, "\n") + "\n\n"
}

// docComment returns the declaration doc comment when present, or an empty string.
func docComment(n *graph.Node) string {
	if n.Decl == nil {
		return ""
	}
	switch d := n.Decl.(type) {
	case *ast.GenDecl:
		if d.Doc != nil {
			return d.Doc.Text()
		}
	case *ast.FuncDecl:
		if d.Doc != nil {
			return d.Doc.Text()
		}
	}
	return ""
}

// codeSnippet reads the source file and returns the declaration lines as a single string.
func codeSnippet(n *graph.Node) string {
	f, err := os.Open(n.Pos.File)
	if err != nil {
		return ""
	}
	defer f.Close()

	var lines []string
	scanner := bufio.NewScanner(f)
	lineNum := 0
	for scanner.Scan() {
		lineNum++
		if lineNum >= n.Range.StartLine && lineNum <= n.Range.EndLine {
			lines = append(lines, scanner.Text())
		}
	}
	return strings.Join(lines, "\n")
}

// incomingLinks returns Obsidian wikilinks for all nodes that n has an outgoing link to.
func incomingLinks(n *graph.Node, nodes []*graph.Node) []string {
	byID := make(map[graph.ID]*graph.Node, len(nodes))
	for _, node := range nodes {
		byID[node.ID] = node
	}

	var links []string
	for _, pair := range link.Pairs(nodes) {
		if pair.Source == n.ID {
			target := byID[pair.Target]
			if target == nil {
				continue
			}
			rel := path.Join(target.Package.PackagePath, FileName(target))
			label := target.Name
			if target.Receiver != "" {
				label = target.Receiver + "." + target.Name
			}
			links = append(links, "[["+rel+"|"+label+"]]")
		}
	}
	return links
}

// propertyNames lists the properties the node reports in a fixed order, so the same record renders
// the same line. A property that does not apply to the node is not listed.
func propertyNames(p graph.NodeProperties) []string {
	var names []string
	if p.Exported {
		names = append(names, "exported")
	}
	if p.Generic {
		names = append(names, "generic")
	}
	if p.EntryPoint {
		names = append(names, "entry_point")
	}
	return names
}

func propertyLine(p graph.NodeProperties) string {
	names := propertyNames(p)
	if len(names) == 0 {
		return ""
	}
	return "[" + strings.Join(names, ", ") + "]"
}

// Read reads the record a note file carries. The frontmatter is read as scalar lines, which is the
// form this package writes, so no YAML reader is needed. A file with no frontmatter block, or a
// marker whose value does not read as a boolean, is reported as an error, because ownership cannot
// be confirmed from such a file.
func Read(file string) (Record, error) {
	data, err := os.ReadFile(file)
	if err != nil {
		return Record{}, fmt.Errorf("vault: cannot read %s: %w", file, err)
	}

	lines := strings.Split(string(data), "\n")
	if len(lines) == 0 || strings.TrimSpace(lines[0]) != "---" {
		return Record{}, fmt.Errorf("vault: %s carries no frontmatter block", file)
	}

	record := Record{}
	for _, line := range lines[1:] {
		line = strings.TrimSpace(line)
		if line == "---" {
			return record, nil
		}
		if line == "" {
			continue
		}
		field, value, ok := strings.Cut(line, ":")
		if !ok {
			return Record{}, fmt.Errorf("vault: %s carries a frontmatter line without a value: %s", file, line)
		}
		value = strings.TrimSpace(value)
		if field == MarkerField {
			if value != "true" && value != "false" {
				return Record{}, fmt.Errorf("vault: %s carries a marker that does not read as a boolean: %s", file, value)
			}
			record.Generated = value == "true"
			continue
		}
		if err := readField(&record, field, value); err != nil {
			return Record{}, fmt.Errorf("vault: %s: %w", file, err)
		}
	}
	return Record{}, fmt.Errorf("vault: %s has no closing frontmatter fence", file)
}

func readField(record *Record, field, value string) error {
	switch field {
	case "module":
		record.Module = value
	case "version":
		record.Version = value
	case "package_path":
		record.PackagePath = value
	case "package":
		record.Package = value
	case "kind":
		record.Kind = value
	case "semantic_type":
		record.SemanticType = value
	case "properties":
		record.Properties = readProperties(value)
	case "file":
		record.File = value
	case "line":
		return readInt(&record.Line, field, value)
	case "column":
		return readInt(&record.Column, field, value)
	case "start_line":
		return readInt(&record.StartLine, field, value)
	case "end_line":
		return readInt(&record.EndLine, field, value)
	}
	return nil
}

func readInt(target *int, field, value string) error {
	number, err := strconv.Atoi(value)
	if err != nil {
		return fmt.Errorf("field %s does not read as a line number: %s", field, value)
	}
	*target = number
	return nil
}

func readProperties(value string) []string {
	value = strings.Trim(strings.TrimSpace(value), "[]")
	if value == "" {
		return nil
	}
	var names []string
	for name := range strings.SplitSeq(value, ",") {
		if name = strings.TrimSpace(name); name != "" {
			names = append(names, name)
		}
	}
	return names
}

// folderOf reports the folder a file sits in, which is the part of the location the file name
// cannot carry.
func folderOf(file string) string {
	return path.Dir(file)
}
